"""Build is secret-free: validate schema and bundle the canonical flavour catalog."""

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))


def main():
    folder = ROOT / "src/nullreference/themes/mafia"
    values = json.loads((folder / "flavour.ru.json").read_text("utf-8"))
    if any(
        not isinstance(k, str) or not isinstance(v, str) or len(v) > 1400 for k, v in values.items()
    ):
        raise ValueError("Invalid default flavour catalog")
    (folder / "texts.py").write_text(
        "# Generated by scripts/build.py from flavour.ru.json\nDEFAULTS = " + repr(values) + "\n",
        encoding="utf-8",
    )
    from nullreference.themes.mafia.commands import manifest

    commands = manifest()
    assert len({c["name"] for c in commands}) == len(commands)
    assert all(len(c["description"]) <= 100 for c in commands)
    (ROOT / "dist").mkdir(exist_ok=True)
    (ROOT / "dist/commands.json").write_text(
        json.dumps(commands, ensure_ascii=False, indent=2), "utf-8"
    )
    from nullreference.themes.mafia.help import TOPICS, render_help

    for topic in TOPICS:
        if len(render_help(topic).encode("utf-16-le")) // 2 > 2000:
            raise ValueError("Help page exceeds Discord's message limit: " + topic)
    (ROOT / "docs").mkdir(exist_ok=True)
    (ROOT / "docs/player-guide.md").write_text(
        "# Справка игрока\n\nСгенерировано из тех же страниц, которые показывает `/help`.\n\n"
        + "\n\n---\n\n".join(render_help(topic) for topic in TOPICS)
        + "\n",
        "utf-8",
    )
    news = [
        (key, value) for key, value in sorted(values.items()) if key.startswith("news_sabotage_")
    ]
    (ROOT / "docs/sabotage-news.md").write_text(
        "# Новости о подрыве влияния\n\n"
        "100 вариантов: по 10 успехов и неудач на преступную семью. "
        "Редактирование без деплоя: `/flavour_edit key:…`.\n\n"
        + "\n\n---\n\n".join(f"## `{key}`\n\n{value}" for key, value in news)
        + "\n",
        "utf-8",
    )
    cargo = [
        (key, value) for key, value in sorted(values.items()) if key.startswith("night_cargo_")
    ]
    (ROOT / "docs/night-shift-cargo.md").write_text(
        "# Грузы «Ночной смены»\n\n"
        "По 6 сюжетов на риск: low / normal / high. "
        "Выбор: `/operation_catalog risk:…`, создание: `/operation_start risk:… route:… cargo:1`. "
        "Сюжеты одного риска имеют одинаковые числовые условия. "
        "Тексты меняются через `/flavour_edit key:night_cargo_low_1` без деплоя.\n\n"
        + "\n\n---\n\n".join(f"## `{key}`\n\n{value}" for key, value in cargo)
        + "\n",
        "utf-8",
    )
    print(f"Validated {len(commands)} commands and {len(values)} flavour templates.")


if __name__ == "__main__":
    main()
